import{a as e}from"./rolldown-runtime-Cyuzqnbw.js";import{Bt as t,Cn as n,Ct as r,Fn as i,Ft as a,Gt as o,Ht as s,Kt as c,Ot as l,Qt as u,Ut as d,bt as f,cn as p,jn as m,ln as ee,on as h,tn as g,un as _,vn as te,wt as v,yn as ne,zt as y}from"./vendor-xzjrkzVH.js";import{t as b}from"./vendor-react-BfNRqZ_Y.js";import{An as x,B as S,Kt as C,R as re,Rn as ie,St as w,Tn as ae,Yt as oe,Zn as se,a as T,bn as ce,c as le,ct as ue,en as E,er as D,ft as O,i as k,ln as de,mr as fe,n as A,ot as pe,pt as me,q as he,r as j,s as ge,ur as _e,vt as ve,wn as ye}from"./vendor-ui-DeDfL_XG.js";import{l as M,n as be,r as xe,s as Se,t as Ce,u as N}from"./index-HIzsHDUw.js";var P=e(i()),we=[{id:`transformer-attention`,title:{"zh-TW":`Transformer 與注意力`,"zh-CN":`Transformer 与注意力`,en:`Transformers and attention`,ja:`Transformer と注意機構`,ko:`Transformer와 어텐션`},content:{"zh-TW":`注意力會比較每個 token 的查詢、鍵和值，將相關上下文加權後送入下一層。多頭注意力讓模型同時觀察語意、順序與長距離關係。`,"zh-CN":`注意力会比较每个 token 的查询、键和值，将相关上下文加权后送入下一层。多头注意力让模型同时观察语义、顺序与长距离关系。`,en:`Attention compares each token query, key, and value, then sends a weighted context to the next layer. Multiple heads track meaning, order, and long-range relationships.`,ja:`注意機構は各トークンのクエリ、キー、バリューを比較し、重み付けした文脈を次の層へ送ります。`,ko:`어텐션은 각 토큰의 쿼리, 키, 값을 비교하고 가중 문맥을 다음 계층으로 전달합니다.`},tags:[`transformer`,`attention`,`注意力`,`注意`,`어텐션`]},{id:`liquid-network`,title:{"zh-TW":`液態神經網路`,"zh-CN":`液态神经网络`,en:`Liquid neural networks`,ja:`液体ニューラルネットワーク`,ko:`액체 신경망`},content:{"zh-TW":`液態神經網路以連續時間狀態方程更新神經元，時間常數與回饋連結會改變它對新訊號和歷史狀態的反應，適合處理動態序列。`,"zh-CN":`液态神经网络以连续时间状态方程更新神经元，时间常数与反馈连接会改变它对新信号和历史状态的反应，适合处理动态序列。`,en:`Liquid neural networks update neurons with continuous-time state equations. Time constants and recurrent links control how they respond to new signals and history.`,ja:`液体ニューラルネットワークは連続時間の状態方程式でニューロンを更新し、時定数と再帰結合で履歴への応答を制御します。`,ko:`액체 신경망은 연속 시간 상태 방정식으로 뉴런을 갱신하며 시간 상수와 순환 연결로 신호와 과거 상태에 반응합니다.`},tags:[`liquid`,`lnn`,`液態`,`液态`,`時間`,`continuous`,`액체`]},{id:`reinforcement-learning`,title:{"zh-TW":`強化學習與人類回饋`,"zh-CN":`强化学习与人类反馈`,en:`Reinforcement learning and human feedback`,ja:`強化学習と人間のフィードバック`,ko:`강화학습과 인간 피드백`},content:{"zh-TW":`獎勵模型會把正確性、有用性、安全性與清晰度轉為分數，策略再依偏好訊號調整輸出分布。這是流程示意，不代表模型逐字即時訓練。`,"zh-CN":`奖励模型会把正确性、有用性、安全性与清晰度转为分数，策略再依偏好信号调整输出分布。`,en:`A reward model converts accuracy, helpfulness, safety, and clarity into a score. The policy then shifts its output distribution toward preferred behavior.`,ja:`報酬モデルは正確性、有用性、安全性、明瞭さをスコア化し、方策はその選好信号に合わせて出力分布を調整します。`,ko:`보상 모델은 정확성, 유용성, 안전성, 명확성을 점수로 바꾸고 정책은 선호 신호에 맞춰 출력 분포를 조정합니다.`},tags:[`rl`,`rlhf`,`reward`,`獎勵`,`奖励`,`強化學習`,`보상`]},{id:`retrieval-generation`,title:{"zh-TW":`檢索增強生成`,"zh-CN":`检索增强生成`,en:`Retrieval-augmented generation`,ja:`検索拡張生成`,ko:`검색 증강 생성`},content:{"zh-TW":`RAG 先從可信來源找出相關片段，再把證據和問題一起送入生成流程。它能讓答案更新且可追溯，但仍需要檢查來源品質。`,"zh-CN":`RAG 先从可信来源找出相关片段，再把证据和问题一起送入生成流程。`,en:`RAG retrieves relevant evidence before generation. It improves freshness and traceability, while source quality still needs review.`,ja:`RAG は生成前に関連する根拠を検索し、情報の鮮度と追跡可能性を高めます。`,ko:`RAG는 생성 전에 관련 근거를 검색해 최신성과 추적 가능성을 높입니다.`},tags:[`rag`,`retrieval`,`檢索`,`检索`,`검색`]}],F=e=>{let t=2166136261;for(let n of e)t^=n.codePointAt(0)??0,t=Math.imul(t,16777619);return t>>>0},I=e=>(e.trim().match(/[A-Za-z0-9]+(?:['_-][A-Za-z0-9]+)*|[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]|[^\s]/gu)??[]).slice(0,32).map((e,t)=>{let n=F(`${t}:${e}`);return{text:e,index:t,id:n,activation:n%1e3/999}}),L=(e,t=.8)=>{let n=Math.max(.08,t);return e.map((t,r)=>{let i=e.map((e,i)=>{let a=t.text.toLocaleLowerCase()===e.text.toLocaleLowerCase()?1.4:.45,o=1/(1+Math.abs(r-i)),s=1-Math.abs(t.activation-e.activation);return Math.exp((a+o+s)/n)}),a=i.reduce((e,t)=>e+t,0)||1;return i.map(e=>e/a)})},R=(e,t)=>{let n=Object.keys(e),r=n.reduce((e,n)=>e+Math.max(0,t[n]),0)||1,i=n.map(n=>{let i=Math.max(0,t[n])/r,a=Math.max(0,Math.min(1,e[n]));return{key:n,signal:a,weight:i,contribution:a*i}});return{total:i.reduce((e,t)=>e+t.contribution,0),breakdown:i}},z=e=>new Se